from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *

@gl.storage.allow
@dataclass
class Endorsement:
    actor: Address
    note: str
    at: str

class Badge(gl.contract.Contract):
    operator: Address
    watch: Address
    goal_id: str
    endorsements: gl.storage.DynArray[Endorsement]

    def __init__(self, watch: str, goal_id: str):
        self.operator = gl.message.sender_address
        self.watch = _address(watch)
        key = goal_id.strip().lower()
        if not key:
            raise gl.vm.UserError('name the goal this badge waits on')
        self.goal_id = key

    @gl.public.write
    def endorse(self, note: str) -> dict:
        status = gl.contract.get_at(self.watch).view().status(self.goal_id)
        if str(status['goal_id']).lower() != self.goal_id:
            raise gl.vm.UserError('that status is about a different goal')
        if not bool(status['in_time']):
            raise gl.vm.UserError('that release has not been seen in time, so this stays shut')
        entry = Endorsement(actor=gl.message.sender_address, note=note.strip()[:200], at=_stamp())
        self.endorsements.append(entry)
        return {'endorsed': True, 'by': entry.actor.as_hex, 'at': entry.at, 'shipped_at': str(status['shipped_at'])}

    @gl.public.view
    def standing(self) -> dict:
        status = gl.contract.get_at(self.watch).view().status(self.goal_id)
        return {'operator': self.operator.as_hex, 'watch': self.watch.as_hex, 'goal_id': self.goal_id, 'shipped': bool(status['shipped']), 'in_time': bool(status['in_time']), 'shipped_at': str(status['shipped_at']), 'last_note': str(status['last_note']), 'open': bool(status['in_time'])}

    @gl.public.view
    def history(self) -> list:
        return [{'actor': e.actor.as_hex, 'note': e.note, 'at': e.at} for e in self.endorsements]

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())
